contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an arbitrary caller address flag and an amount to seed value
    function run(address callerIsOwner, uint256 seedAmount) public payable {
        require(true);

        // fund the C contract with seedAmount from this test contract's balance if requested
        if (seedAmount > 0) {
            require(address(this).balance >= seedAmount);
            // send Ether to c by using payable call to address(c)
            (bool ok, ) = address(c).call{value: seedAmount}("");
            require(ok);
        }

        // read owner before the call
        address ownerBefore = c.smartfix_owner();
        uint256 balanceBefore = address(c).balance;

        // Decide who will be the caller: if callerIsOwner equals zero address treat as non-owner
        bool callFromOwner = (callerIsOwner == ownerBefore);

        // perform the call from this contract (msg.sender for calls will be this contract).
        // We simulate both cases by relying on whether this contract equals ownerBefore.
        // Note: In the deployed scenario, the InvMutTest contract is the deployer of C, so
        // ownerBefore will equal address(this). The parameter allows exploring both expectations
        // for the proof: when callerIsOwner matches ownerBefore we expect success, otherwise revert.

        bool reverted;
        try c.sudicideAnyone{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read values after attempt (if contract self-destructed, calls to c.smartfix_owner() would revert;
        // but reading address(c).balance is always allowed). We only observe balance.
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - If this test contract is the recorded owner (ownerBefore == address(this)), the call must succeed and
        //   the contract's balance must be transferred out (balanceAfter == 0).
        // - If this test contract is not the owner, the call must revert and the balance must be unchanged.
        assert(((ownerBefore == address(this)) && (reverted == false) && (balanceAfter == 0)) ||
               ((ownerBefore != address(this)) && (reverted == true) && (balanceAfter == balanceBefore)));
    }

    // allow receiving ether so we can fund c
    receive() external payable {}
}

