contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public test function taking a caller address and an amount to try to send
    function run(address caller, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // record observable state before the call
        address ownerBefore = c.smartfix_owner();
        uint256 balanceBefore = address(c).balance;

        // Try to call sudicideAnyone from this contract (note: msg.sender for c will be this contract)
        bool reverted;
        try c.sudicideAnyone{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempting the call, read observables again (getter and balance)
        address ownerAfter = c.smartfix_owner();
        uint256 balanceAfter = address(c).balance;

        // General rule:
        // If this contract is not the owner (i.e., ownerBefore != address(this)), then the call must revert
        // and neither owner nor balance of c may have changed. If this contract is the owner, the call may succeed
        // (leading to contract destruction), in which case we cannot rely on getters; so we only assert the non-owner case here.
        assert((ownerBefore != address(this)) ? (reverted && ownerAfter == ownerBefore && balanceAfter == balanceBefore) : true);
    }

    receive() external payable {}
}

