contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an address parameter to range over possible callers
    function run(address caller) public payable {
        require(true);

        // observe before-state
        address ownerBefore = c.smartfix_owner();
        uint256 balanceBefore = address(c).balance;

        // perform the call: simulate caller by using low-level call from this contract to c with encoded selector
        // Note: sudicideAnyone has selector bytes4(keccak256("sudicideAnyone()"))
        bool reverted;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("sudicideAnyone()"))));
        // Since the checker will run this once with msg.sender == InvMutTest when calling c,
        // we treat the provided `caller` parameter as an abstract input: the rule will assert behavior when
        // caller != ownerBefore (i.e., this call should have reverted in that case). However, actual call's
        // msg.sender is this contract; we can only observe public getters and revert flag `ok` from the call.
        reverted = !ok;

        // observe after-state
        address ownerAfter = c.smartfix_owner();
        uint256 balanceAfter = address(c).balance;

        // General rule: if the abstract input caller is different from the stored ownerBefore,
        // then the call must have reverted and owner and balance remain unchanged.
        assert((caller != ownerBefore) ? (reverted && ownerAfter == ownerBefore && balanceAfter == balanceBefore) : true);
    }

    receive() external payable { }
}

